old:
  // Only a real change moves the card. A small difference (a few pixels) is stored for the
  // next open but not applied, so the card never twitches while the keyboard is up.
  var next = Math.round(ratio * fullH), prev = srKbSeen;
  srKbSeen = next;
  if (srOpen && (!prev || Math.abs(next - prev) > fullH * 0.015)) relay();
};

new:
  // The card is planned for a slightly tall keyboard, so it already fits. It moves only when the
  // real keyboard is taller than planned (the card would be covered). A shorter keyboard is
  // remembered and used from the next open, so the card never twitches while the keyboard is up.
  var next = Math.round(ratio * fullH), prev = srKbSeen || Math.round(fullH * 0.44);
  srKbLearned = next;
  if (srOpen && next > prev + fullH * 0.01) { srKbSeen = next; relay(); }
};
